import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadBhimlatData(){const e=readFileSync(resolve(__dirname,"../../bhimlat-falls-explorer/bhimlat-data.js"),"utf-8");return new Function(e+"\nreturn { BHIMLAT_INFO, HEIGHT_COMPARISONS, SEASONAL_DATA, NEARBY_ATTRACTIONS, GALLERY_IMAGES, REFERENCES };")()}describe("Bhimlat Falls Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadBhimlatData()}),describe("BHIMLAT_INFO metadata",()=>{it("contains correct Bhimlat Falls location, height, and Pandava legend attributes",()=>{expect(e.BHIMLAT_INFO.id).toBe("bhimlat-falls"),expect(e.BHIMLAT_INFO.title).toContain("Bhimlat Falls"),expect(e.BHIMLAT_INFO.height).toContain("60 Meters"),expect(e.BHIMLAT_INFO.legendHero).toContain("Bhima")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.BHIMLAT_INFO.quickStats)).toBe(!0),expect(e.BHIMLAT_INFO.quickStats.length).toBe(6)})}),describe("HEIGHT_COMPARISONS & SEASONAL_DATA",()=>{it("contains height comparisons and seasonal flow data",()=>{expect(Array.isArray(e.HEIGHT_COMPARISONS)).toBe(!0),expect(e.HEIGHT_COMPARISONS.length).toBeGreaterThanOrEqual(4);const t=e.HEIGHT_COMPARISONS.find(e=>"Bhimlat Falls"===e.name);expect(t).toBeDefined(),expect(t.heightMeters).toBe(60),expect(Array.isArray(e.SEASONAL_DATA)).toBe(!0),expect(e.SEASONAL_DATA.length).toBeGreaterThanOrEqual(3)})}),describe("NEARBY_ATTRACTIONS & REFERENCES",()=>{it("contains nearby Bundi attractions and references",()=>{expect(Array.isArray(e.NEARBY_ATTRACTIONS)).toBe(!0),expect(e.NEARBY_ATTRACTIONS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});